            inv = F32(1.0) / p if mult == "recip" else None
            if inv is not None:
                A[j, :] = A[j, :] * inv
            else:
                A[j, :] = A[j, :] / p
            # the augmented part too, same op
            if inv is not None:
                X[j, :] = X[j, :] * inv
            else:
                X[j, :] = X[j, :] / p
