                m = A[i, j] / p if mult == "div" else A[i, j] * (F32(1.0) / p)
                if use_fma:
                    A[i, :] = (A[i, :].astype(np.float64)
                               - m.astype(np.float64) * A[j, :].astype(np.float64)).astype(F32)
                    X[i, :] = (X[i, :].astype(np.float64)
                               - m.astype(np.float64) * X[j, :].astype(np.float64)).astype(F32)
